guided.solution:
def pokes_needed(appears_at, poke_interval):
    t, n = 0, 0
    while True:
        n += 1
        if t >= appears_at:
            return n
        t += poke_interval

for a in [0, 59, 60, 601]:
    print(pokes_needed(a, 60))

def alert_message(context):
    return f"{context['dag_id']}.{context['task_id']} failed on try {context['try_number']} for {context['ds']}: {context['exception']}"

print(alert_message({"dag_id": "sales", "task_id": "load", "try_number": 3, "ds": "2025-03-04", "exception": "connection refused"}))

