independent.solution:
loaded = {"orders": 30, "customers": 5, "returns": 20}
limits = {"orders": 12, "customers": 48, "returns": 24}
now = 36
for table in sorted(loaded):
    age = now - loaded[table]
    print(table, "age", age, "STALE" if age > limits[table] else "ok")
